using SupportAgent.Core.Models;
namespace SupportAgent.Core.Interfaces;
public interface IInvoiceCalculator { decimal LineTotal(decimal quantity, decimal unitPrice, decimal discount, decimal tax); decimal InvoiceTotal(IEnumerable<InvoiceItem> items); decimal Outstanding(decimal total, IEnumerable<Payment> payments); }
public interface IProductService { Task<Product?> GetProductAsync(int id, CancellationToken token = default); Task<IReadOnlyList<Product>> SearchProductsAsync(string? search = null, CancellationToken token = default); }
public interface IInvoiceService { Task<InvoiceDetail?> GetInvoiceAsync(int id, CancellationToken token = default); Task<InvoiceDetail?> GetInvoiceByNumberAsync(string number, CancellationToken token = default); Task<IReadOnlyList<InvoiceListItem>> GetCustomerInvoicesAsync(int customerId, CancellationToken token = default); Task<IReadOnlyList<InvoiceListItem>> SearchAsync(string? search, string? status, CancellationToken token = default); Task<CustomerBalance> GetCustomerBalanceAsync(int customerId, CancellationToken token = default); Task<IReadOnlyList<InvoiceListItem>> GetOutstandingInvoicesAsync(int customerId, CancellationToken token = default); Task<SalesSummary> GetSalesSummaryAsync(DateTime start, DateTime end, CancellationToken token = default); }
public interface IPaymentService { Task<IReadOnlyList<PaymentDetail>> GetInvoicePaymentsAsync(int invoiceId, CancellationToken token = default); }
public interface IInventoryService { Task<InventoryStatus?> GetInventoryAsync(int productId, CancellationToken token = default); Task<IReadOnlyList<InventoryStatus>> GetLowStockProductsAsync(CancellationToken token = default); }
public interface IInvoiceDocumentService { Task<byte[]?> GenerateAsync(int invoiceId, CancellationToken token = default); }
